import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Skill27 retains its existing early actor capture and pair receipt; project only the WORLD companion query. */
public final class CompanionWeaponSceneMethods {
 static final String P="local/lito381/server/",PC=P+"ClientSession",H=P+"NativeCompanionTargets";
 static AbstractInsnNode previous(AbstractInsnNode n){do{n=n.getPrevious();}while(n!=null&&n.getOpcode()<0);return n;}
 static ClassNode read(JarFile j)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(PC+".class"))).accept(c,ClassReader.SKIP_DEBUG);return c;}
 static byte[] bytes(ClassNode c){var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static void patch(ClassNode c){int roots=0,snapshots=0,iterators=0,gates=0;for(var m:c.methods)if(m.name.equals("nativeMaterialWorldWeaponBreakBody")){
  roots++;for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode v&&v.owner.equals(PC)&&v.name.equals("classicWorldCompanionSnapshots")){
   if(!(previous(v) instanceof VarInsnNode owner&&owner.var==13))throw new AssertionError("exact companion owner slot");AbstractInsnNode store=v;while(store!=null&&!(store instanceof VarInsnNode a&&a.getOpcode()==ASTORE&&a.var==13))store=previous(store);if(store==null)throw new AssertionError("owner store");var cast=previous(store);var next=previous(cast);var load=previous(next);if(!(cast instanceof TypeInsnNode t&&t.desc.equals(PC)&&next instanceof MethodInsnNode nextCall&&nextCall.name.equals("next")&&load instanceof VarInsnNode l&&l.var==12))throw new AssertionError("exact companion iterator");AbstractInsnNode iterator=load;while(iterator!=null&&!(iterator instanceof VarInsnNode a&&a.getOpcode()==ASTORE&&a.var==12))iterator=previous(iterator);if(iterator==null||!(previous(iterator) instanceof MethodInsnNode call&&call.owner.equals("java/util/List")&&call.name.equals("iterator")))throw new AssertionError("list iterator");var members=previous(previous(iterator));if(!(members instanceof MethodInsnNode membersCall&&membersCall.owner.equals(PC)&&membersCall.name.equals("classicWorldMembers")))throw new AssertionError("unchanged original player list producer");var add=new InsnList();add.add(new VarInsnNode(ALOAD,0));add.add(new MethodInsnNode(INVOKESTATIC,H,"owners","(Ljava/util/List;L"+PC+";)Ljava/util/List;",false));m.instructions.insertBefore(previous(iterator),add);iterators++;m.instructions.insertBefore(v,new VarInsnNode(ALOAD,0));m.instructions.set(v,new MethodInsnNode(INVOKESTATIC,H,"snapshots","(L"+PC+";L"+PC+";)Ljava/util/List;",false));snapshots++;
  }
  for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode v&&v.owner.equals(PC)&&v.name.equals("sameClassicWorldMap")&&previous(v) instanceof VarInsnNode owner&&owner.var==9){m.instructions.set(v,new MethodInsnNode(INVOKESTATIC,H,"same","(L"+PC+";L"+PC+";)Z",false));gates++;}
 }if(roots!=1||snapshots!=1||iterators!=1||gates!=2)throw new AssertionError("exact skill27 actor ports "+roots+" "+snapshots+" "+iterators+" "+gates);}
 public static void main(String[]args)throws Exception{try(var j=new JarFile(args[1])){var c=read(j);patch(c);var expected=bytes(c);if(args[0].equals("splice")){var out=Path.of(args[2]).resolve(PC+".class");Files.createDirectories(out.getParent());Files.write(out,expected);}else try(var candidate=new JarFile(args[2])){if(!Arrays.equals(expected,bytes(read(candidate))))throw new AssertionError("exact WORLD weapon companion projection");}}System.out.println("PASS one skill27 companion iterator/snapshot and two companion gates; player predicates and BATTLE unchanged");}
}
